 38	  }
 39	  .display {
 40	    position: relative;
 41	    height: 96px;
 42	    margin-bottom: 16px;
 43	    padding: 0 12px;
 44	    display: flex;
 45	    align-items: flex-end;
 46	    justify-content: flex-end;
 47	    overflow: hidden;
 48	    border-radius: 14px;
 49	    background: var(--screen);
 50	    color: var(--text);
 51	    font-size: 48px;
 52	    font-weight: 300;
 53	    line-height: 1.6;
 54	    white-space: nowrap;
 55	    font-variant-numeric: tabular-nums;
 56	  }
 57	  /* Open groups, shown as a row of "(" in the corner. Kept out of textContent. */
 58	  .display::before {
 59	    content: attr(data-open);
 60	    position: absolute;
 61	    top: 8px;
 62	    left: 12px;
 63	    color: var(--fn);
 64	    font-size: 16px;
 65	    line-height: 1;
 66	    letter-spacing: 2px;
 67	  }
 68	  .keys {
 69	    display: grid;
 70	    grid-template-columns: repeat(4, 1fr);
 71	    gap: 10px;
 72	  }
 73	  button {
 74	    height: 64px;
 75	    border: 0;
 76	    border-radius: 14px;
 77	    background: var(--key);
 78	    color: var(--text);
 79	    font: inherit;
 80	    font-size: 24px;
 81	    cursor: pointer;
 82	    transition: background 0.1s, transform 0.05s;
 83	    -webkit-tap-highlight-color: transparent;
 84	  }
 85	  button:hover { background: var(--key-hover); }
 86	  button:active { transform: scale(0.96); }
 87	  button:focus-visible { outline: 2px solid var(--op); outline-offset: 2px; }
 88	  .op { background: var(--op); color: #1c1f24; }
 89	  .op:hover { background: var(--op-hover); }
 90	  .op.active { background: var(--text); color: var(--op); }
 91	  .fn { background: var(--fn); color: #1c1f24; }
 92	  .fn:hover { background: var(--fn-hover); }
 93	  .wide { grid-column: span 2; }
 94	</style>
 95	</head>
 96	<body>
 97	<main class="calc">
 98	  <div class="display" data-testid="calc-display" data-value="0" data-error="false" data-open="" role="status" aria-live="polite">0</div>
 99	  <div class="keys">
100	    <button type="button" class="wide" data-testid="key-lparen" aria-label="Open group">(</button>
101	    <button type="button" class="wide" data-testid="key-rparen" aria-label="Close group">)</button>
102	
103	    <button type="button" class="fn" data-testid="key-clear">AC</button>
104	    <button type="button" class="fn" data-testid="key-sign" aria-label="Change sign">±</button>
105	    <button type="button" class="fn" data-testid="key-percent" aria-label="Percent">%</button>
106	    <button type="button" class="op" data-testid="key-div" data-op="/" aria-label="Divide">÷</button>
107	
108	    <button type="button" data-testid="key-7" data-digit="7">7</button>
109	    <button type="button" data-testid="key-8" data-digit="8">8</button>
110	    <button type="button" data-testid="key-9" data-digit="9">9</button>
111	    <button type="button" class="op" data-testid="key-mul" data-op="*" aria-label="Multiply">×</button>
112	
113	    <button type="button" data-testid="key-4" data-digit="4">4</button>
114	    <button type="button" data-testid="key-5" data-digit="5">5</button>
115	    <button type="button" data-testid="key-6" data-digit="6">6</button>
116	    <button type="button" class="op" data-testid="key-sub" data-op="-" aria-label="Subtract">−</button>
117	
118	    <button type="button" data-testid="key-1" data-digit="1">1</button>
119	    <button type="button" data-testid="key-2" data-digit="2">2</button>
120	    <button type="button" data-testid="key-3" data-digit="3">3</button>
121	    <button type="button" class="op" data-testid="key-add" data-op="+" aria-label="Add">+</button>
122	
123	    <button type="button" class="wide" data-testid="key-0" data-digit="0">0</button>
124	    <button type="button" data-testid="key-dot" aria-label="Decimal point">.</button>
125	    <button type="button" class="op" data-testid="key-equals" aria-label="Equals">=</button>
126	  </div>
127	</main>
128	<script>
129	(function () {
130	  var MAX_DIGITS = 16;
131	
132	  var display = document.querySelector('[data-testid="calc-display"]');
133	  var opKeys = document.querySelectorAll('[data-op]');
134	
135	  // value: the number currently shown when no entry is being typed.
136	  //   Always the exact computed value. Never rounded; see format().
137	  // entry: the string being typed, or null.
138	  // locked: true when entry holds a finished number (made by ± or % from a
139	  //   result, or by %). It displays formatted; the next digit starts fresh.
140	  // acc/op: the left operand and pending operator.
141	  // stack: the acc/op of each enclosing group, innermost last.
142	  // error: true after division by zero (or any non-finite result).
143	  var state;
144	
145	  function reset() {
146	    state = { value: 0, entry: null, locked: false, acc: null, op: null, stack: [], error: false };
147	  }
148	
149	  function fail() {
150	    state = { value: NaN, entry: null, locked: false, acc: null, op: null, stack: [], error: true };
151	  }
152	
153	  function compute(a, op, b) {
154	    switch (op) {
155	      case '+': return a + b;
156	      case '-': return a - b;
157	      case '*': return a * b;
158	      case '/': return b === 0 ? NaN : a / b;
159	    }
160	    return b;
161	  }
162	
163	  function currentValue() {
164	    return state.entry !== null ? Number(state.entry) : state.value;
165	  }
166	
167	  // Presentation only: rounds to at most 10 significant digits, drops
168	  // trailing zeros, and uses exponential notation only when the rounded
169	  // magnitude is >= 1e10 or < 1e-9. Never feed the result back into state.
170	  function format(n) {
171	    if (n === 0) return '0';
172	    var m = n.toExponential(9).match(/^(-?)(\d)\.(\d+)e([+-]\d+)$/);
173	    var sign = m[1];
174	    var digits = (m[2] + m[3]).replace(/0+$/, '') || '0';
175	    var exp = Number(m[4]);
176	    if (exp >= 10 || exp < -9) {
177	      var mantissa = digits.length > 1 ? digits[0] + '.' + digits.slice(1) : digits;
178	      return sign + mantissa + 'e' + (exp < 0 ? '-' : '+') + Math.abs(exp);
179	    }
180	    var intPart, fracPart;
181	    if (exp >= 0) {
182	      while (digits.length < exp + 1) digits += '0';
183	      intPart = digits.slice(0, exp + 1);
184	      fracPart = digits.slice(exp + 1);
185	    } else {
186	      intPart = '0';
187	      fracPart = new Array(-exp).join('0') + digits;
188	    }
189	    return sign + intPart + (fracPart ? '.' + fracPart : '');
190	  }
191	
192	  function render() {
193	    var value = currentValue();
194	    var text = state.error ? 'Error' : state.entry !== null && !state.locked ? state.entry : format(value);
195	    display.textContent = text;
196	    display.setAttribute('data-value', String(value));
197	    display.setAttribute('data-error', String(state.error));
198	    display.setAttribute('data-open', new Array(state.stack.length + 1).join('('));
199	    display.style.fontSize = text.length > 12 ? Math.max(20, Math.floor(48 * 12 / text.length)) + 'px' : '';
200	    for (var i = 0; i < opKeys.length; i++) {
201	      var k = opKeys[i];
202	      k.classList.toggle('active', state.entry === null && state.op === k.getAttribute('data-op'));
203	    }
204	  }
205	
206	  function inputDigit(d) {
207	    var e = state.entry;
208	    if (e === null || state.locked || e === '0') {
209	      state.entry = d;
210	      state.locked = false;
211	    } else if (e === '-0') {
212	      state.entry = '-' + d;
213	    } else if (e.replace(/[-.]/g, '').length < MAX_DIGITS) {
214	      state.entry = e + d;
215	    }
216	  }
217	
218	  function inputDot() {
219	    if (state.entry === null || state.locked) {
220	      state.entry = '0.';
221	      state.locked = false;
222	    } else if (state.entry.indexOf('.') === -1) {
223	      state.entry += '.';
224	    }
225	  }
226	
227	  // ± and % act on the current entry. With no entry, they act on the shown
228	  // result, or on a new 0 entry when an operator is waiting for its operand.
229	  // A group that was just opened counts as waiting for an operand too.
230	  function takeEntry() {
231	    if (state.entry !== null) return;
232	    var groupStart = state.stack.length > 0 && state.acc === null;
233	    state.locked = state.op === null && !groupStart;
234	    state.entry = state.locked ? String(state.value) : '0';
235	  }
236	
237	  function toggleSign() {
238	    takeEntry();
239	    var e = state.entry;
240	    state.entry = e.charAt(0) === '-' ? e.slice(1) : '-' + e;
241	  }
242	
243	  // Shifts the decimal exponent instead of dividing, so 0.07 % gives
244	  // exactly 0.0007 rather than 0.0007000000000000001.
245	  function percent() {
246	    takeEntry();
247	    var parts = String(Number(state.entry)).split('e');
248	    var n = Number(parts[0] + 'e' + (Number(parts[1] || 0) - 2));
249	    if (n === 0 && state.entry.charAt(0) === '-') n = -0;
250	    state.entry = Object.is(n, -0) ? '-0' : String(n);
251	    state.locked = true;
252	  }
253	
254	  // Immediate execution: an operator key first finishes the operation already
255	  // waiting, strictly left to right, with no precedence (2 + 3 × 4 = 20).
256	  // The display then always shows a real running result.
257	  function inputOperator(op) {
258	    if (state.entry !== null) {
259	      var b = Number(state.entry);
260	      state.value = state.op !== null ? compute(state.acc, state.op, b) : b;
261	      state.entry = null;
262	    }
263	    if (!isFinite(state.value)) return fail();
264	    state.acc = state.value;
265	    state.op = op;
266	  }
267	
268	  // Opens a group: the pending acc/op wait on the stack while the group is
269	  // worked out on its own. Ignored while a number is being entered.
270	  function openGroup() {
271	    if (state.entry !== null) return;
272	    state.stack.push({ acc: state.acc, op: state.op });
273	    state.value = 0;
274	    state.acc = null;
275	    state.op = null;
276	  }
277	
278	  // Finishes the group, restores the outer acc/op, and hands the group's
279	  // result to them as a finished entry.
280	  function closeGroup() {
281	    if (state.stack.length === 0) return;
282	    var b = currentValue();
283	    var result = state.op !== null ? compute(state.acc, state.op, b) : b;
284	    if (!isFinite(result)) return fail();
285	    var outer = state.stack.pop();
286	    state.acc = outer.acc;
287	    state.op = outer.op;
288	    state.value = result;
289	    state.entry = String(result);
290	    state.locked = true;
291	  }
292	
293	  // Closes any groups left open, then finishes the calculation.
294	  function equals() {
295	    while (state.stack.length > 0 && !state.error) closeGroup();
296	    if (state.error) return;
297	    if (state.op === null) {
298	      if (state.entry !== null) {
299	        state.value = Number(state.entry);
300	        state.entry = null;
301	      }
302	      return;
303	    }
304	    var b = currentValue();
305	    state.value = compute(state.acc, state.op, b);
306	    state.entry = null;
307	    state.acc = null;
308	    state.op = null;
309	    if (!isFinite(state.value)) fail();
310	  }
311	
312	  // In the error state every key except clear is ignored.
313	  function press(action) {
314	    if (state.error && action !== reset) return;
315	    action();
316	    render();
317	  }
318	
319	  document.querySelector('.keys').addEventListener('click', function (ev) {
320	    var btn = ev.target.closest('button');
321	    if (!btn) return;
322	    var id = btn.getAttribute('data-testid');
323	    if (btn.hasAttribute('data-digit')) {
324	      press(function () { inputDigit(btn.getAttribute('data-digit')); });
325	    } else if (btn.hasAttribute('data-op')) {
326	      press(function () { inputOperator(btn.getAttribute('data-op')); });
327	    } else if (id === 'key-sign') {
328	      press(toggleSign);
329	    } else if (id === 'key-percent') {
330	      press(percent);
331	    } else if (id === 'key-lparen') {
332	      press(openGroup);
333	    } else if (id === 'key-rparen') {
334	      press(closeGroup);
335	    } else if (id === 'key-dot') {
336	      press(inputDot);
337	    } else if (id === 'key-equals') {
338	      press(equals);
339	    } else if (id === 'key-clear') {
340	      press(reset);
341	    }
342	  });
343	
344	  document.addEventListener('keydown', function (ev) {
345	    if (ev.ctrlKey || ev.metaKey || ev.altKey) return;
346	    var k = ev.key;
347	    if (/^[0-9]$/.test(k)) {
348	      press(function () { inputDigit(k); });
349	    } else if (k === '.' || k === ',') {
350	      press(inputDot);
351	    } else if (k === '+' || k === '-' || k === '*' || k === '/') {
352	      press(function () { inputOperator(k); });
353	    } else if (k === '(') {
354	      press(openGroup);
355	    } else if (k === ')') {
356	      press(closeGroup);
357	    } else if (k === '%') {
358	      press(percent);
359	    } else if (k === 'Enter' || k === '=') {
360	      press(equals);
361	    } else if (k === 'Escape' || k === 'Delete') {
362	      press(reset);
363	    } else {
364	      return;
365	    }
366	    ev.preventDefault();
367	  });
368	
369	  reset();
370	  render();
371	})();
372	</script>
373	</body>
374	</html>

